24	#[derive(Debug, Clone)]
25	pub(crate) struct StatusRateLimitRow {
26	    /// Human-readable row label, such as `"5h limit"` or `"Credits"`.
27	    pub label: String,
28	    /// Value payload for the row.
29	    pub value: StatusRateLimitValue,
30	}
31	
32	/// Display value variants for a single rate-limit row.
33	#[derive(Debug, Clone)]
34	pub(crate) enum StatusRateLimitValue {
35	    /// Percent-based usage window with optional reset timestamp text.
36	    Window {
37	        /// Percent of the window that has been consumed.
38	        percent_used: f64,
39	        /// Localized reset string, or `None` when unknown.
40	        resets_at: Option<String>,
41	    },
42	    /// Plain text value used for non-window rows.
43	    Text(String),
44	}
45	
46	/// Availability state for rate-limit data shown in status output.
47	#[derive(Debug, Clone)]
48	pub(crate) enum StatusRateLimitData {
49	    /// Snapshot data is recent enough for normal rendering.
50	    Available(Vec<StatusRateLimitRow>),
51	    /// Snapshot data exists but is older than the staleness threshold.
52	    Stale(Vec<StatusRateLimitRow>),
53	    /// No snapshot data is currently available.
54	    Missing,
55	}
56	
57	/// Maximum age before a snapshot is considered stale in status output.
58	pub(crate) const RATE_LIMIT_STALE_THRESHOLD_MINUTES: i64 = 15;
59	
60	/// Display-friendly representation of one usage window from a snapshot.
61	#[derive(Debug, Clone)]
62	pub(crate) struct RateLimitWindowDisplay {
63	    /// Percent used for the window.
64	    pub used_percent: f64,
65	    /// Human-readable local reset time.
66	    pub resets_at: Option<String>,
67	    /// Window length in minutes when provided by the server.
68	    pub window_minutes: Option<i64>,
69	}
70	
71	impl RateLimitWindowDisplay {
72	    fn from_window(window: &RateLimitWindow, captured_at: DateTime<Local>) -> Self {
73	        let resets_at_utc = window
74	            .resets_at
75	            .and_then(|seconds| DateTime::<Utc>::from_timestamp(seconds, 0))
76	            .map(|dt| dt.with_timezone(&Local));
77	        let resets_at = resets_at_utc.map(|dt| format_reset_timestamp(dt, captured_at));
78	
79	        Self {
80	            used_percent: window.used_percent,
81	            resets_at,
82	            window_minutes: window.window_minutes,
83	        }
84	    }
85	}
