112	/// Converts a protocol snapshot into UI-friendly display data.
113	///
114	/// Pass the timestamp from the same observation point as `snapshot`; supplying a significantly
115	/// older or newer `captured_at` can produce misleading reset labels and stale classification.
116	#[cfg(test)]
117	pub(crate) fn rate_limit_snapshot_display(
118	    snapshot: &RateLimitSnapshot,
119	    captured_at: DateTime<Local>,
120	) -> RateLimitSnapshotDisplay {
121	    rate_limit_snapshot_display_for_limit(snapshot, "codex".to_string(), captured_at)
122	}
123	
124	pub(crate) fn rate_limit_snapshot_display_for_limit(
125	    snapshot: &RateLimitSnapshot,
126	    limit_name: String,
127	    captured_at: DateTime<Local>,
128	) -> RateLimitSnapshotDisplay {
129	    RateLimitSnapshotDisplay {
130	        limit_name,
131	        captured_at,
132	        primary: snapshot
133	            .primary
134	            .as_ref()
135	            .map(|window| RateLimitWindowDisplay::from_window(window, captured_at)),
136	        secondary: snapshot
137	            .secondary
138	            .as_ref()
139	            .map(|window| RateLimitWindowDisplay::from_window(window, captured_at)),
140	        credits: snapshot.credits.as_ref().map(CreditsSnapshotDisplay::from),
141	    }
142	}
